   [225]={next_id=226, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在这之后，我可能会一次又一次地陷入这种境地，殿下你也要一次又一次地把我拉出来吗？", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [226]={next_id=227, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当然，我从来不食言——直到你认为自己的命运有了新的方向，直到你愿意被我的血“拯救”。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [227]={next_id=228, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="面对你的回答，赫梅克低着头，不知在想什么。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [228]={next_id=229, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="过了一会后，她缓缓抬头，对着你说到。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [229]={next_id=230, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="既然如此，那可让你有的受了。我建议殿下抱着随时抛弃我这种“将死之人”的想法，会轻松很多。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [230]={next_id=231, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这得看我的判断来，你只管做你自己就好。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [231]={next_id=232, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="赫梅克点头致意，再次与你稍微拉开了些距离。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
